CREATE OR REPLACE FUNCTION public.claim_provider_cancellation(p_subscription_id uuid) RETURNS SETOF public.provider_cancellation_requests LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.provider_cancellation_requests SET state='processing',lease_until=now()+interval '2 minutes',attempts=attempts+1,updated_at=now() WHERE subscription_id=p_subscription_id AND state IN ('pending','processing') AND next_retry_at<=now() AND (lease_until IS NULL OR lease_until<now()) RETURNING * $$;
REVOKE ALL ON FUNCTION public.claim_provider_cancellation(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_provider_cancellation(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.prevent_cancelled_payment_reactivation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='active' AND (OLD.cancel_at_period_end OR OLD.cancelled_at IS NOT NULL OR OLD.status IN ('cancelled','refunded','refunded_duplicate','cancel_scheduled') OR EXISTS(SELECT 1 FROM public.refund_requests WHERE subscription_id=OLD.id AND status IN ('processed','approved','processing') AND keep_access IS NOT TRUE)) THEN RAISE EXCEPTION 'cancelled_subscription_cannot_reactivate'; END IF; RETURN NEW; END $$;
CREATE TABLE public.post_cancel_refund_operations (charge_id text PRIMARY KEY, subscription_id uuid NOT NULL REFERENCES public.subscriptions(id), user_id uuid NOT NULL, amount numeric NOT NULL CHECK(amount>0), reason text NOT NULL, state text NOT NULL DEFAULT 'reserved' CHECK(state IN ('reserved','processing','confirmed','uncertain')), refund_request_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.post_cancel_refund_operations TO authenticated;
GRANT ALL ON public.post_cancel_refund_operations TO service_role;
ALTER TABLE public.post_cancel_refund_operations ENABLE ROW LEVEL SECURITY;
CREATE POLICY admins_read_post_cancel_refund_operations ON public.post_cancel_refund_operations FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin'));
CREATE OR REPLACE FUNCTION public.admin_post_cancel_renewals() RETURNS TABLE(subscription_id uuid,user_id uuid,email text,validapay_subscription_id text,cancelled_at timestamptz,refunded_at timestamptz,charge_id text,paid_at timestamptz,amount numeric,refund_recorded boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF current_setting('request.jwt.claim.role',true) IS DISTINCT FROM 'service_role' AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_roles.user_id=auth.uid() AND role='admin') THEN RAISE EXCEPTION 'admin_required'; END IF; RETURN QUERY WITH r AS (SELECT rr.subscription_id,min(rr.processed_at) AS refunded_at FROM public.refund_requests rr WHERE rr.status='processed' AND rr.keep_access IS NOT TRUE GROUP BY rr.subscription_id), e AS (SELECT DISTINCT ON(coalesce(v.charge_id,v.subscription_id||':cycle:'||coalesce(v.payload->'currentCycle'->>'cycleNumber',v.id::text))) v.subscription_id,v.charge_id,coalesce(nullif(v.payload->'currentCycle'->>'paidAt','')::timestamptz,v.created_at) AS paid_at,coalesce(nullif(v.payload->'currentCycle'->>'amount','')::numeric,v.amount) AS amount FROM public.validapay_webhook_events v WHERE v.event='subscription.renewed' AND (v.status='PAID' OR v.payload->'currentCycle'->>'status'='PAID') ORDER BY coalesce(v.charge_id,v.subscription_id||':cycle:'||coalesce(v.payload->'currentCycle'->>'cycleNumber',v.id::text)),v.created_at DESC) SELECT s.id,s.user_id,p.email,s.validapay_subscription_id,s.cancelled_at,r.refunded_at,e.charge_id,e.paid_at,e.amount,EXISTS(SELECT 1 FROM public.refund_requests rr WHERE rr.subscription_id=s.id AND rr.status IN ('pending','processed','processing','approved') AND e.charge_id IS NOT NULL AND (rr.charge_id=e.charge_id OR rr.provider_response->>'chargeId'=e.charge_id)) FROM public.subscriptions s LEFT JOIN r ON r.subscription_id=s.id JOIN e ON e.subscription_id=s.validapay_subscription_id LEFT JOIN public.profiles p ON p.user_id=s.user_id WHERE (s.cancelled_at IS NOT NULL OR r.refunded_at IS NOT NULL) AND e.paid_at>least(s.cancelled_at,r.refunded_at) ORDER BY e.paid_at DESC; END $$;
REVOKE ALL ON FUNCTION public.admin_post_cancel_renewals() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_post_cancel_renewals() TO authenticated,service_role;